UNLOCK TABLES;
DROP TABLE IF EXISTS `InventoryMovement`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `InventoryMovement` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `inventoryId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `type` enum('INITIAL','ADJUSTMENT','RESERVE','RELEASE','SHIP','RETURN_RESTOCK','IMPORT') COLLATE utf8mb4_unicode_ci NOT NULL,
  `quantityDelta` int NOT NULL DEFAULT '0',
  `reservedDelta` int NOT NULL DEFAULT '0',
  `quantityAfter` int NOT NULL,
  `reservedAfter` int NOT NULL,
  `reason` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `referenceType` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `referenceId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `actorId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `InventoryMovement_inventoryId_createdAt_idx` (`inventoryId`,`createdAt`),
  KEY `InventoryMovement_referenceType_referenceId_idx` (`referenceType`,`referenceId`),
  CONSTRAINT `InventoryMovement_inventoryId_fkey` FOREIGN KEY (`inventoryId`) REFERENCES `Inventory` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
