DROP TABLE IF EXISTS `Order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Order` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `orderNumber` varchar(24) COLLATE utf8mb4_unicode_ci NOT NULL,
  `customerId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `idempotencyKey` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('PENDING_CONFIRMATION','CONFIRMED','PROCESSING','SHIPPED','OUT_FOR_DELIVERY','DELIVERED','CANCELLED','RETURN_REQUESTED','RETURN_APPROVED','RETURN_REJECTED','RETURNED','REFUND_PENDING','REFUNDED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_CONFIRMATION',
  `paymentMethod` enum('COD') COLLATE utf8mb4_unicode_ci NOT NULL,
  `paymentStatus` enum('PENDING','COD_PENDING','PAID','FAILED','REFUND_PENDING','REFUNDED') COLLATE utf8mb4_unicode_ci NOT NULL,
  `shippingMethod` enum('STANDARD','EXPRESS') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'STANDARD',
  `currency` varchar(3) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'INR',
  `itemsSubtotal` decimal(12,2) NOT NULL,
  `mrpTotal` decimal(12,2) NOT NULL,
  `discountTotal` decimal(12,2) NOT NULL DEFAULT '0.00',
  `shippingTotal` decimal(12,2) NOT NULL DEFAULT '0.00',
  `codFee` decimal(12,2) NOT NULL DEFAULT '0.00',
  `taxTotal` decimal(12,2) NOT NULL DEFAULT '0.00',
  `grandTotal` decimal(12,2) NOT NULL,
  `refundedTotal` decimal(12,2) NOT NULL DEFAULT '0.00',
  `couponId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `couponCode` varchar(40) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipName` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shipPhone` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shipLine1` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shipLine2` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipLandmark` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipCity` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shipState` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shipPincode` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL,
  `shipCountry` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'IN',
  `notes` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `placedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `cancelledAt` datetime(3) DEFAULT NULL,
  `deliveredAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `Order_orderNumber_key` (`orderNumber`),
  UNIQUE KEY `Order_customerId_idempotencyKey_key` (`customerId`,`idempotencyKey`),
  KEY `Order_customerId_placedAt_idx` (`customerId`,`placedAt`),
  KEY `Order_status_placedAt_idx` (`status`,`placedAt`),
  KEY `Order_paymentStatus_idx` (`paymentStatus`),
  KEY `Order_placedAt_idx` (`placedAt`),
