/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `OrderItem` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `orderId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sellerOrderId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sellerId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `listingId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `productId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `variantId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `categoryId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `productName` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `variantName` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sku` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sellerName` varchar(160) COLLATE utf8mb4_unicode_ci NOT NULL,
  `imageUrl` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hsnCode` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `unitPrice` decimal(12,2) NOT NULL,
  `unitMrp` decimal(12,2) NOT NULL,
  `quantity` int NOT NULL,
  `cancelledQuantity` int NOT NULL DEFAULT '0',
  `returnedQuantity` int NOT NULL DEFAULT '0',
  `lineSubtotal` decimal(12,2) NOT NULL,
  `discountAmount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `sellerFundedDiscount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `shippingAmount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `taxRate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `taxAmount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `taxInclusive` tinyint(1) NOT NULL DEFAULT '1',
  `lineTotal` decimal(12,2) NOT NULL,
  `commissionRate` decimal(5,2) NOT NULL DEFAULT '0.00',
  `commissionFixed` decimal(12,2) NOT NULL DEFAULT '0.00',
  `commissionAmount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `status` enum('PENDING_CONFIRMATION','CONFIRMED','PROCESSING','SHIPPED','OUT_FOR_DELIVERY','DELIVERED','CANCELLED','RETURN_REQUESTED','RETURN_APPROVED','RETURN_REJECTED','RETURNED','REFUND_PENDING','REFUNDED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING_CONFIRMATION',
  `isReturnable` tinyint(1) NOT NULL DEFAULT '1',
  `returnWindowDays` int NOT NULL DEFAULT '7',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `OrderItem_orderId_idx` (`orderId`),
  KEY `OrderItem_sellerOrderId_idx` (`sellerOrderId`),
  KEY `OrderItem_sellerId_createdAt_idx` (`sellerId`,`createdAt`),
  KEY `OrderItem_productId_idx` (`productId`),
  KEY `OrderItem_listingId_fkey` (`listingId`),
  CONSTRAINT `OrderItem_listingId_fkey` FOREIGN KEY (`listingId`) REFERENCES `SellerProductListing` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `OrderItem_orderId_fkey` FOREIGN KEY (`orderId`) REFERENCES `Order` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `OrderItem_productId_fkey` FOREIGN KEY (`productId`) REFERENCES `Product` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `OrderItem_sellerId_fkey` FOREIGN KEY (`sellerId`) REFERENCES `Seller` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `OrderItem_sellerOrderId_fkey` FOREIGN KEY (`sellerOrderId`) REFERENCES `SellerOrder` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
