DROP TABLE IF EXISTS `Product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Product` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(220) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `highlights` json DEFAULT NULL,
  `specifications` json DEFAULT NULL,
  `tags` json DEFAULT NULL,
  `searchText` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `categoryId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `brandId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ownerSellerId` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hsnCode` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('DRAFT','PENDING_REVIEW','APPROVED','REJECTED','SUSPENDED','ARCHIVED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT',
  `rejectionReason` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `isFeatured` tinyint(1) NOT NULL DEFAULT '0',
  `isReturnable` tinyint(1) NOT NULL DEFAULT '1',
  `returnWindowDays` int NOT NULL DEFAULT '7',
  `codAvailable` tinyint(1) NOT NULL DEFAULT '1',
  `videoUrl` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `minPrice` decimal(12,2) DEFAULT NULL,
  `maxMrp` decimal(12,2) DEFAULT NULL,
  `maxDiscountPct` int NOT NULL DEFAULT '0',
  `inStock` tinyint(1) NOT NULL DEFAULT '0',
  `ratingAvg` decimal(3,2) NOT NULL DEFAULT '0.00',
  `ratingCount` int NOT NULL DEFAULT '0',
  `soldCount` int NOT NULL DEFAULT '0',
  `viewCount` int NOT NULL DEFAULT '0',
  `publishedAt` datetime(3) DEFAULT NULL,
  `submittedAt` datetime(3) DEFAULT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `deletedAt` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `Product_slug_key` (`slug`),
  KEY `Product_status_categoryId_idx` (`status`,`categoryId`),
  KEY `Product_ownerSellerId_status_idx` (`ownerSellerId`,`status`),
  KEY `Product_brandId_idx` (`brandId`),
  KEY `Product_status_isFeatured_idx` (`status`,`isFeatured`),
  KEY `Product_status_publishedAt_idx` (`status`,`publishedAt`),
  KEY `Product_status_soldCount_idx` (`status`,`soldCount`),
  KEY `Product_status_minPrice_idx` (`status`,`minPrice`),
  KEY `Product_categoryId_fkey` (`categoryId`),
  FULLTEXT KEY `Product_title_searchText_idx` (`title`,`searchText`),
  CONSTRAINT `Product_brandId_fkey` FOREIGN KEY (`brandId`) REFERENCES `Brand` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Product_categoryId_fkey` FOREIGN KEY (`categoryId`) REFERENCES `Category` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `Product_ownerSellerId_fkey` FOREIGN KEY (`ownerSellerId`) REFERENCES `Seller` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
